  /* ==================== PC-56 TENANT-2c · bulk listing upload (W128 + W2355–W2356) ==================== */
  'limport.title': 'Bulk upload listings',
  'limport.subtitle': 'CSV or Excel — one row per lot. Every row is validated before anything is created; a bad row never blocks the good ones.',
  'limport.trustPath': 'Bulk-created listings walk the normal path: draft → member consent → QC → published. Bulk speeds entry, it never skips trust — nothing here reaches a buyer without a reviewer approving it.',
  'limport.consentNote': 'Each row lists someone else’s produce, so each member must have recorded their on-behalf consent (voice or app tap). Rows without it are flagged for a fix, never silently dropped — their produce, their yes.',
  'limport.kycGap': 'The canon’s “KYC pending — draft allowed, publish blocks until verified” is half-built on purpose: the draft IS allowed, but no KYC gate exists on publish anywhere on this platform (the per-role KYC map governs payouts and has no listing purpose). Inventing one here would apply a rule to imported lots and not to console-created ones — named as backend work instead of faked.',
  'limport.templateHeading': 'Template',
  'limport.templateNote': 'Columns: {columns}. Generated from the same list the importer parses, so the template cannot drift from the parser.',
  'limport.templateRequired': 'Only phone (whose produce) and product (what) must be filled — everything else has a sensible absence. Price is per unit; the unit column decides which. A per-kilo price on a per-quintal sheet is caught and offered as a fix.',
  'limport.templateDownload': 'Download template (CSV)',
  'limport.loadError': 'Upload history could not load — your listings are unaffected. Reload to retry.',
  'limport.empty': 'No upload yet. Take the template to your collection centre — paper first, upload after, works fine.',
  'limport.jobsHeading': 'Recent uploads',
  'limport.unnamedFile': 'uploaded file',
  'limport.triage': '{total} rows · {create} will create a draft · {dupes} already listed (skipped, never duplicated) · {fixable} fixable · {invalid} unusable',
  'limport.hash': 'file sha256 {hash}',
  'limport.validatedAt': 'validated {at}',
  'limport.issueRow': 'row {row}: {message}',
  'limport.issueSuggestion': 'suggestion: {suggestion} (nothing is applied automatically)',
  'limport.validate': 'Validate every row',
  'limport.confirm': 'Create {n} drafts',
  'limport.nothingToCreate': 'Nothing to create — every usable row is already listed. Your catalogue is up to date.',
  'limport.cancel': 'Cancel',
  'limport.seeDrafts': 'See the drafts →',
  'limport.ok.validated': 'Validated. Nothing was created — the triage below is what this file WOULD do.',
  'limport.ok.confirmed': 'Import running. Each row becomes a draft and goes to QC; refresh to follow it.',
  'limport.ok.cancelled': 'Upload cancelled. Nothing was created.',
  'limport.error.validate': 'Validation did not run. Nothing was created.',
  'limport.error.confirm': 'This upload has already moved on — refresh to see where it is. Nothing was imported twice.',
  'limport.error.cancel': 'The upload could not be cancelled — refresh to see its current state.',
  'limport.error.notValidatable': 'This upload type cannot be validated row by row, so it cannot be confirmed here.',
  'limport.error.changed': 'The file changed after it was validated — upload and validate it again, so what you approve is what gets applied.',
  'limport.error.failed': 'The file could not be read at all (format, missing columns, or unreachable upload). Nothing was created.',
  'limport.idempotentNote': 'Re-uploading the same file cannot double-create: each row is keyed by its own lot (member + product + quantity + price), so the same lot twice in one file is one draft.',

