  'od.snapshot.recorded': 'The charge rules that priced this order are recorded on it, so a rule edited or expired later cannot change what this page says about this order.',
  'od.snapshot.beforeSnapshot': 'This order was placed before the charge rules began being recorded with it (they are, from now on). The amounts above are exactly what was charged; the RULES behind them cannot be re-derived, so nothing here guesses them.',
  'od.snapshot.noCharges': 'No buyer-side charge applied to this order, so there is no rule to record.',
  'od.tdsNote': 'A note on TDS, because the section matters: this platform deducts under 194-O (the marketplace operator’s deduction on the seller’s gross) at SETTLEMENT — it appears on the settlement statement, not on the order row. Section 194Q is the buyer’s own deduction on purchases above the annual threshold and is the buyer’s filing, not ours. ₹0 here means no deduction applied at order time, never that one was waived.',

