  // PC-56 TENANT-4a · W143/W144 — the ORGANISATION's wallet and its ledger.
  'wal.title': 'Wallet',
  'wal.intro': 'Your organisation\'s three accounts (main · commission · hold), all backed by the append-only, hash-chained ledger. Every figure here is the sum of your own ledger entries — not a cached balance.',
  'wal.notYourPersonalWallet': 'This is the organisation’s money. Your personal wallet is in the member app; it is a different account and never mixes with this one.',
  'wal.restricted': 'Organisation balances need the wallet.org_view permission. Ask an admin — the ledger is unaffected either way.',
  'wal.loadError': 'Balances could not be loaded. The ledger is unaffected and payouts run on schedule. Retry.',
  'wal.frozen': 'frozen',
  'wal.account.main': 'main',
  'wal.account.commission': 'commission',
  'wal.account.hold': 'hold',
  'wal.accountMeaning.main': 'Spendable now — milk bills, scheme disbursals and loan disbursals are paid from here.',
  'wal.accountMeaning.commission': 'Commission your organisation has earned, credited when an order completes and reversed if it is refunded.',
  'wal.accountMeaning.hold': 'Money frozen against a dispute. Nothing writes to this account today — see below.',
  'wal.state.reconciled': 'ledger and cache agree',
  'wal.state.drifted': 'cache disagrees — ledger shown',
  'wal.state.never_used': 'never used',
  'wal.driftNotice': 'The cached balance says {cached}, a difference of {drift}. The figure above is the ledger’s own sum, which is the book of record. Platform reconciliation will pick this up; nothing is lost.',
  'wal.holdNothingReserved': 'This reads zero because nothing is reserved for promotions right now. The only money this account ever holds is coupon discounts reserved from Main at checkout, waiting to be paid to the seller at settlement — there is no dispute freeze on your wallet.',
  'wal.holdPromotionReservations': 'Coupon discounts reserved from Main when buyers applied your coupons, waiting to be paid to the seller at settlement (or returned to Main if the order is cancelled). Recorded in the ledger.',
  'wal.holdNeverWritten': 'The hold account has no entries at all — it has never been written since the ledger was created.',
  'wal.gapsTitle': 'Not built — and named rather than drawn',
  'wal.gap.add_funds': 'Adding funds by UPI: there is no organisation top-up anywhere in the platform yet. A form that took an amount and had nowhere to send it would look like it moved money, so there is no button.',
  'wal.gap.payout_bank_change': 'Changing the payout bank account (owner + checker + a 24-hour cooling period) is not built. Payout accounts today belong to individual members, verified through KYC. Until the control is real it is not offered here.',
  'wal.gap.tenant_hold_freeze': 'Freezing part of a payment against a dispute is not built. Escrow holds the buyer’s whole payment for the order instead, and the dispute screen says so.',
  'wal.todayTitle': 'Today’s movement',
  'wal.todayEmpty': 'Nothing has moved through the organisation wallet yet today. Sales, payouts and fees appear here as they happen.',
  'wal.healthTitle': 'Ledger health',
  'wal.health.cached_vs_ledger': 'Your cached balances match the sum of your own entries',
  'wal.health.own_chain': 'Your account’s hash chain, recomputed entry by entry',
  'wal.health.platform_recon': 'Platform-wide zero-sum and gateway reconciliation',
  'wal.healthState.ok': 'checked — ok',
  'wal.healthState.attention': 'needs attention',
  'wal.healthState.unverifiable': 'could not be checked',
  'wal.healthState.not_ours_to_assert': 'run by the platform',
  'wal.healthPlatformNote': 'Zero-sum and gateway reconciliation run over the whole ledger, which every organisation shares. The platform runs them and is accountable for them; this console will not restate “0 breaks” about other organisations’ money. What it does check is above: your own balances against your own entries, and your own chain.',
  'wal.chain.intact': 'intact — every entry hashes to its stored value and every link matches',
  'wal.chain.headMismatch': 'the chain walks cleanly but the account’s head pointer disagrees with its last entry — raise this with the platform',
  'wal.chain.hashMismatch': 'an entry does not hash to its stored value — raise this with the platform immediately',
  'wal.chain.chainBreak': 'a link does not match the entry before it — raise this with the platform immediately',
  'wal.chain.incomplete': 'too many entries to walk in one read, so this is unchecked rather than intact',
  'wal.chain.empty': 'no entries yet, so there is nothing to verify',
  'wal.escrowTitle': 'Escrow (platform-held, not yours yet)',
  'wal.escrowHeld': 'Buyer money for {count} of your in-flight orders. It sits in platform escrow until delivery confirms and is not part of your balances. Nobody, including us, spends escrow.',
  'wal.escrowNone': 'No buyer money is being held for you right now.',
  'wal.escrowBasis': 'Basis: the net of escrow entries carrying your organisation’s id — captures add to it, completions and refunds take from it. Arithmetic off the ledger, not a cached figure.',
  'wal.openLedger': 'Open the ledger — every entry',
  'wal.ledgerTitle': 'Wallet transactions',
  'wal.ledgerIntro': 'The ledger, append-only: every business event is one transaction whose entries sum to zero. Filters are date-bounded and default to the last 30 days.',
  'wal.ledgerEmpty': 'Sales, payouts, fees and refunds moving through the organisation wallet appear here as they happen.',
  'wal.ledgerEmptyFiltered': 'No entries match these filters in this window. Widen the dates or clear a filter — the ledger keeps ten years, partitioned by month.',
  'wal.ledgerLoadError': 'The ledger view could not be loaded. The ledger itself is append-only and safe. Retry.',
  'wal.filterAccount': 'Account',
  'wal.filterAllAccounts': 'All accounts',
  'wal.filterType': 'Transaction type',
  'wal.filterAllTypes': 'All types',
  'wal.filterFrom': 'From',
  'wal.filterTo': 'To',
  'wal.applyFilters': 'Apply',
  'wal.windowClamped': 'This window was longer than 366 days, so it was shortened. Ask for a narrower range to see an exact period.',
  'wal.exportCsv': 'Export CSV',
  'wal.exportReady': 'Export ready: {rows} entries, with a receipt carrying the row count, a sha256 of the data and who asked for it.',
  'wal.exportBlocked.noPermission': 'Exporting needs the wallet.org_view permission.',
  'wal.exportBlocked.windowTooWide': 'Narrow the date range before exporting — exports are bounded to 366 days.',
  'wal.exportBlocked.nothingToExport': 'There is nothing in this window to export.',
  'wal.err.exportTooLarge': 'This window holds more entries than one file may carry. Narrow the date range — a statement that stopped mid-month would be read as complete.',
  'wal.err.exportFailed': 'The export could not be produced. Nothing was recorded and nothing changed.',
  'wal.err.windowTooWide': 'Dates must be a valid range of 366 days or fewer.',
  'wal.colWhen': 'When',
  'wal.colTxn': 'Transaction',
  'wal.colType': 'Type',
  'wal.colAccount': 'Account',
  'wal.colReference': 'Reference',
  'wal.colAmount': 'Amount',
  'wal.colBalanceAfter': 'Balance after (that account)',
  'wal.noEditByDesign': 'There is no edit control on this screen by design. A mistake is corrected by a reversal entry, so the history always tells the whole story — and the database refuses an update even if a screen asked for one.',
  'wal.keysetOnly': 'Pages move forward and back, never by number: on an append-only ledger a page number would point somewhere else tomorrow.',

